playlist_query='Woodstock Reimagined: Festival Vibes'
access_token=spotify_token

page_index=0
page_limit=20
matches=[]
while True:
    res=apis.spotify.show_playlist_library(access_token=access_token, query=playlist_query, page_index=page_index, page_limit=page_limit)
    # res may have list or object; print to inspect
    print('page', page_index, 'res', res)
    if not res:
        break
    # attempt to treat res as list
    if isinstance(res, list):
        for pl in res:
            if pl.get('title')==playlist_query:
                matches.append(pl)
    else:
        # if dict
        if 'playlists' in res:
            for pl in res['playlists']:
                if pl.get('title')==playlist_query:
                    matches.append(pl)
    page_index+=1
    if page_index>20:
        break
print('matches_count', len(matches))
print(matches)

